-- ----------------------------
-- Table structure for activities
-- ----------------------------
DROP TABLE IF EXISTS `activities`;
CREATE TABLE `activities`  (
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用（软删除）',
  `id` int NOT NULL AUTO_INCREMENT COMMENT '动态唯一标识',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '动态类型：rating、comment、question、answer、favorite、add_shop等',
  `target_id` int NOT NULL COMMENT '关联目标ID（如评论ID、店铺ID等）',
  `target_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '目标实体类型，便于前端跳转',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '动态摘要，如\"评论了店铺XX\"',
  `shop_id` int NULL DEFAULT NULL COMMENT '关联店铺ID，前端跳转用',
  `user_id` int NOT NULL COMMENT '产生动态的用户',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `fk_activiti_shops_dabab224`(`shop_id` ASC) USING BTREE,
  INDEX `idx_activities_user_id_6f80e4`(`user_id` ASC, `created_at` ASC) USING BTREE,
  CONSTRAINT `fk_activiti_shops_dabab224` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_activiti_users_e638e970` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Activities 表 - 动态表' ROW_FORMAT = Dynamic;

