-- ----------------------------
-- Table structure for comment_replies
-- ----------------------------
DROP TABLE IF EXISTS `comment_replies`;
CREATE TABLE `comment_replies`  (
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用（软删除）',
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '回复唯一标识',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '回复内容',
  `like_count` int NOT NULL DEFAULT 0 COMMENT '点赞数（冗余字段）',
  `comment_id` bigint NOT NULL COMMENT '所属一级评论',
  `reply_to_user_id` int NULL DEFAULT NULL COMMENT '被回复用户ID（仅用于前端展示 @username 前缀）',
  `user_id` int NOT NULL COMMENT '回复用户',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `fk_comment__users_6dc93c20`(`reply_to_user_id` ASC) USING BTREE,
  INDEX `fk_comment__users_8a7141c9`(`user_id` ASC) USING BTREE,
  INDEX `idx_comment_rep_comment_a7aec5`(`comment_id` ASC, `created_at` ASC) USING BTREE,
  CONSTRAINT `fk_comment__shop_com_4aacb416` FOREIGN KEY (`comment_id`) REFERENCES `shop_comments` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_comment__users_6dc93c20` FOREIGN KEY (`reply_to_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_comment__users_8a7141c9` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'CommentReplies 表 — 二级回复' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of comment_replies
-- ----------------------------

