DROP TABLE IF EXISTS `content_likes`;
CREATE TABLE `content_likes`  (
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用（软删除）',
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '点赞唯一标识',
  `entity_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '被点赞内容类型：shop_comment / comment_reply / shop_question / question_answer',
  `entity_id` bigint NOT NULL COMMENT '被点赞内容ID（BigInt 兼容所有互动实体的主键类型）',
  `user_id` int NOT NULL COMMENT '点赞用户',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_content_lik_entity__264592`(`entity_type` ASC, `entity_id` ASC) USING BTREE,
  INDEX `idx_content_lik_user_id_3225dd`(`user_id` ASC, `entity_type` ASC, `entity_id` ASC, `created_at` ASC) USING BTREE,
  CONSTRAINT `fk_content__users_558d1b88` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'ContentLikes 表 — 内容点赞表（多态关联）' ROW_FORMAT = Dynamic;

