  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用（软删除）',
  `id` int NOT NULL AUTO_INCREMENT COMMENT '唯一标识',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标签名称，如\'火锅\'、\'华农西门\'',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序顺序（同一类型内）',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否为默认值',
  `extra` json NULL COMMENT '扩展字段，如存储图标URL、颜色值等',
