  CONSTRAINT `fk_dict_dat_dict_typ_2eb11014` FOREIGN KEY (`dict_type_id`) REFERENCES `dict_types` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'DictData 表 — 字典数据表' ROW_FORMAT = Dynamic;

