-- ----------------------------
-- Table structure for feedbacks
-- ----------------------------
DROP TABLE IF EXISTS `feedbacks`;
CREATE TABLE `feedbacks`  (
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用（软删除）',
  `id` int NOT NULL AUTO_INCREMENT COMMENT '反馈唯一标识',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'complaint=举报 | edit_request=勘误',
  `target_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '反馈对象类型：shop / comment / image',
  `target_id` int NOT NULL COMMENT '被反馈对象ID',
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '用户填写的补充描述',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'pending' COMMENT 'pending=待处理 | approved=已采纳 | rejected=已驳回',
  `admin_id` int NULL DEFAULT NULL COMMENT '处理管理员',
  `reason_id` int NOT NULL COMMENT '反馈原因',
  `user_id` int NOT NULL COMMENT '提交用户',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `fk_feedback_users_ffbbf6ac`(`admin_id` ASC) USING BTREE,
  INDEX `fk_feedback_dict_dat_e86d8df3`(`reason_id` ASC) USING BTREE,
  INDEX `fk_feedback_users_fcbb7783`(`user_id` ASC) USING BTREE,
  INDEX `idx_feedbacks_status_0b7b73`(`status` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_feedbacks_target__746c6d`(`target_type` ASC, `target_id` ASC) USING BTREE,
  CONSTRAINT `fk_feedback_dict_dat_e86d8df3` FOREIGN KEY (`reason_id`) REFERENCES `dict_data` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_feedback_users_fcbb7783` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_feedback_users_ffbbf6ac` FOREIGN KEY (`admin_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Feedback 表 — 统一反馈工单' ROW_FORMAT = Dynamic;

