  `ip_address` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '客户端IP地址',
  `user_agent` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '客户端设备信息',
  `session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '会话ID（未登录用户追踪用）',
  `operator_id` int NULL DEFAULT NULL COMMENT '操作用户（未登录可为空）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_operation_l_operato_20feba`(`operator_id` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_operation_l_action_27b553`(`action` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_operation_l_target__2dbd6a`(`target_type` ASC, `target_id` ASC) USING BTREE,
  CONSTRAINT `fk_operatio_users_86a3f307` FOREIGN KEY (`operator_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'OperationLog 表 — 统一操作日志' ROW_FORMAT = Dynamic;

