-- ----------------------------
-- Table structure for view_history
-- ----------------------------
DROP TABLE IF EXISTS `view_history`;
CREATE TABLE `view_history`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最后更新时间',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用（软删除）',
  `viewed_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '最近浏览时间',
  `shop_id` int NOT NULL COMMENT '被浏览店铺',
  `user_id` int NOT NULL COMMENT '浏览用户',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uid_view_histor_user_id_3bdbcf`(`user_id` ASC, `shop_id` ASC) USING BTREE,
  INDEX `fk_view_his_shops_31449c98`(`shop_id` ASC) USING BTREE,
  CONSTRAINT `fk_view_his_shops_31449c98` FOREIGN KEY (`shop_id`) REFERENCES `shops` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_view_his_users_406afe33` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'ViewHistory 表 — 浏览历史' ROW_FORMAT = Dynamic;

